public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create an adjacency list to represent the graph
    List<Integer>[] graph = new List[n * n];
    for (int i = 0; i < n * n; i++) {
        graph[i] = new ArrayList<>();
    }

    // Populate the adjacency list with the given paths
    for (int[] path : paths) {
        int from = path[0] * n + path[1];
        int to = path[2] * n + path[3];
        graph[from].add(to);
        graph[to].add(from);
    }

    // Use a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n * n];
    int startNode = start[0] * n + start[1];
    int endNode = end[0] * n + end[1];

    queue.add(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        if (currentNode == endNode) {
            return "can be travelled";
        }
        for (int neighbor : graph[currentNode]) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

