public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n / 2 + 1][n + 1][sum + 1];
    dp[0][0][0] = true;

    for (int k = 1; k <= n / 2; k++) {
        for (int i = n - 1; i >= k; i--) {
            for (int j = 0; j <= sum; j++) {
                dp[k][i][j] = dp[k][i + 1][j];
                if (j >= nums[i]) {
                    dp[k][i][j] |= dp[k - 1][i + 1][j - nums[i]];
                }
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        if (sum * k % n == 0 && dp[k][0][sum * k / n]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
