public int minInsertions(String s) {
    int open = 0; // To keep track of open parentheses
    int insertions = 0; // To count the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++;
        } else {
            // Found a closing parenthesis
            if (open > 0) {
                open--; // Match with an open parenthesis if available
            } else {
                insertions++; // Need to insert an open parenthesis to balance
            }
            // Check the next character if it is also a closing parenthesis
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next closing parenthesis as they form a pair
            } else {
                insertions++; // Need an extra closing parenthesis to balance
            }
        }
    }

    // At the end, we might still have unmatched open parentheses
    insertions += open * 2;

    return insertions;
}

