private int backtrack(String s, HashSet<String> used) {
    if (s.isEmpty()) {
        return 0;
    }
    int maxUnique = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (!used.contains(prefix)) {
            used.add(prefix);
            maxUnique = Math.max(maxUnique, 1 + backtrack(s.substring(i), used));
            used.remove(prefix);
        }
    }
    return maxUnique;
}

